rule.example:
public class Example {
    void bad() {
        String name = "joke";                      // violation
        for (int i = 0; i < 3; i++) { }            // violation
        for (String s : names) { }                 // violation
    }

    void good() {
        var name = "joke";
        for (var i = 0; i < 3; i++) { }
        for (var s : names) { }

        int uninitialized;                         // no violation: var needs an initializer
        String nothing = null;                     // no violation: null has no type to infer
        int[] shorthand = {1, 2};                  // no violation: var forbids this form
        Runnable task = () -> { };                 // no violation: a lambda needs a target type
        Supplier<String> make = String::new;       // no violation: so does a method reference
        int a = 1, b = 2;                          // no violation: var forbids multiple declarators
    }
}

public class Example {
    private static int count;
    private static final Map<String, String> REGISTRY = new HashMap<>();

    static String format(int n) { return "" + n; }        // violation: a helper, not state
    static int get() { return count; }                    // violation: a read, not a write
    static void register(String k, String v) {            // violation: not a write to the field
        REGISTRY.put(k, v);
    }

    static void bump() { count++; }                       // no violation: writes private static state
    static void reset() { count = 0; }                    // no violation: so does this
    public static void main(String[] args) { }            // no violation: the JVM requires static

    String betterAsAnInstanceMethod(int n) { return "" + n; }
}

final class Utility {                                     // no instance methods, private constructor
    private Utility() { }

    static String format(int n) { return "" + n; }        // no violation: a utility class
}

public class Example {
    private boolean check() { return true; }        // violation
    protected boolean verify() { return true; }     // violation

    boolean inspect() { return true; }              // no violation: package-private
    public boolean isValid() { return true; }       // no violation: public API

    private Example() { }                           // no violation: constructors are out of scope

    @Override
    protected void finalize() { }                   // no violation: visibility is not chosen here

    @SuppressWarnings("PMD.AvoidPrivateAndProtectedMethods")
    protected void extensionPoint() { }             // no violation: a deliberate, reviewed API
}

public class Example {
    boolean check() { return true; }                     // violation: an unmarked seam

    @VisibleForTesting
    boolean verify() { return true; }                    // no violation

    public boolean isValid() { return true; }            // no violation: not package-private

    @Override
    void run() { }                                       // no violation: visibility is inherited

    @Test
    void reportsTheViolation() { }                       // no violation: a JUnit test method
}
